import inspect

class Depends:
    def __init__(self, fn):
        self.fn = fn

calls = []  # records every time a dependency really runs

def get_settings():
    calls.append("get_settings")
    return {"db": "test.db"}

def get_session(settings=Depends(get_settings)):
    calls.append("get_session")
    return "session@" + settings["db"]

def get_user(settings=Depends(get_settings), session=Depends(get_session)):
    calls.append("get_user")
    return "user via " + session

def resolve(fn, cache):
    # Walk the signature; build each Depends depth-first, once per request
    kwargs = {}
    for name, p in inspect.signature(fn).parameters.items():
        if isinstance(p.default, Depends):
            dep = p.default.fn
            if dep not in cache:          # cache keyed on the function
                cache[dep] = resolve(dep, cache)
            kwargs[name] = cache[dep]
    return fn(**kwargs)

def route(user=Depends(get_user), settings=Depends(get_settings)):
    return user                           # a "path operation"

for i in (1, 2):
    calls.clear()
    cache = {}                        # fresh cache for every request
    result = resolve(route, cache)
    print("request", i, "->", result)
    print("  dependency runs:", calls)
